import{_ as t,c as e,o as a,ah as s,ao as p,ap as n}from"./chunks/framework.Dq2_gudl.js";const g=JSON.parse('{"title":"雀一羽さえ忘れられない — その子は決して見過ごされなかった","description":"イエスは、雀一羽さえ父の知らないうちには落ちないと言われました。マタイと詩篇が語る、動物への神の顧み。","frontmatter":{"title":"雀一羽さえ忘れられない — その子は決して見過ごされなかった","description":"イエスは、雀一羽さえ父の知らないうちには落ちないと言われました。マタイと詩篇が語る、動物への神の顧み。"},"headers":[],"relativePath":"ja/pets-in-heaven/not-one-sparrow-forgotten.md","filePath":"ja/pets-in-heaven/not-one-sparrow-forgotten.md"}'),r={name:"ja/pets-in-heaven/not-one-sparrow-forgotten.md"};function i(l,o,c,h,d,u){return a(),e("div",null,[...o[0]||(o[0]=[s('<div class="pl-quote"><p>「あの子はただの小さな動物でした。世界は覚えていてくれるでしょうか。それとも、私だけでしょうか」</p><p class="pl-quote-soft">イエスは一度この問いに答えてくださいました。そしてその答えは、私たちの期待よりずっとやさしいのです。</p></div><section class="pl-section"><h2>1. イエスは言われました。雀一羽さえ、父なしには落ちない</h2><blockquote><p><strong>マタイの福音書 10:29-31</strong></p><p>&quot;Are not two sparrows sold for a farthing? and one of them shall not fall on the ground without your Father. But the very hairs of your head are all numbered. Fear ye not therefore, ye are of more value than many sparrows.&quot;</p></blockquote><p>イエスの時代、雀は買えるものの中で最も安いもののひとつでした。小銭一枚で二羽。誰も特別に気にかけない、そんな命でした。</p><p>それなのにイエスは言われました。<strong>あなたがたの父の許しがなければ、その一羽も地に落ちることはない。</strong></p><p>ここでの「落ちる」は、死を意味します。イエスは、最も安い小鳥の死さえ、神が知らず、心にかけていない事故ではない、と言っておられるのです。その子の旅立ちは、見られていました。記録されています。</p><p>あなたのその子が、世間から「ただの動物」と呼ばれるような小さな存在だったなら、このみことばはあなたのために書かれました。神は雀を覚えておられます。あなたのその子を忘れたりはなさいません。</p></section><section class="pl-section"><h2>2. その子を養われた — 一日も欠かさずに</h2><blockquote><p><strong>詩篇 147:9</strong></p><p>&quot;He giveth to the beast his food, and to the young ravens which cry.&quot;</p></blockquote><p>ダビデは別のところでもこう書いています。</p><blockquote><p><strong>詩篇 36:6</strong></p><p>&quot;…O LORD, thou preservest man and beast.&quot;</p></blockquote><p>「人と獣」 — 原語のこのことばは、野生の獣も家の獣も含みます。神は動物を、ご自分が保たれる者のリストに入れておられます。ついでではなく、私たちと並べて。</p><p>それは何を意味するのでしょう。その子の最初の日から最後の日まで、毎日の食事、毎年の冬、あなたが家にいなかった時間のすべてを、あの神がご覧になっていたということです。あなたは一人で世話していると思っていました。神と一緒に世話していたのです。</p></section><section class="pl-section"><h2>3. その子は神のもの — そこがいちばん安全な場所です</h2><blockquote><p><strong>詩篇 50:10-11</strong></p><p>&quot;For every beast of the forest is mine, and the cattle upon a thousand hills. I know all the fowls of the mountains: and the wild beasts of the field are mine.&quot;</p></blockquote><p>神は言われます。「森のすべての獣はわたしのもの。千の丘の家畜も。山のすべての鳥を知っている。」</p><p>あなたのその子は、決してあなたの所有物ではありませんでした。神があなたの世話にゆだねてくださった贈り物でした。そして贈り主がそれを取り戻すとき、捨てるのではなく、<strong>ご自分のもとへ連れて帰ってくださいます</strong>。</p><p>今その子をどう世話しておられるのか、どこにいるのか、あなたの声を覚えているのかは分かりません。でも、それが誰の御手なのかは分かります。雀まで数えられた、その御手です。</p><p class="pl-quote-soft">今日、ひとことばだけ心に残せるなら、これを残してください。</p></section><div class="pl-quote"><p>「その子は、神のまなざしから一度も外れたことがありません。今も。」</p></div><section class="pl-section"><h2>こんな祈りをしてみてください</h2><p>「主よ、あの子をこの何年も私にゆだねてくださって感謝します。<br>私に見えないところでも顧みてくださって感謝します。<br>もう抱きしめられないけれど、あなたの御手が私の手より大きいことを知っています。<br>どうかあの子を、雀一羽を顧みるように顧みてください。<br>そして私も顧みてください。とても会いたいのです。アーメン。」</p><p><a href="/ja/pets-in-heaven/">← Pets in Heaven に戻る</a> ｜ 次の記事：<a href="/ja/pets-in-heaven/rainbow-bridge-covenant">虹の橋のむこう側</a></p></section><div class="pl-cta"><h2>その子には名前があります。</h2><p>PetLoss に、その子の名前と、あなただけが知っていた小さな癖を書いてみてください。そんな細部は残される価値があります。</p><a class="pl-download" href="https://apps.apple.com/us/app/petloss-memorial-healing/id6757967412">App Store でダウンロード</a></div><div class="pl-bible"><h3>みことばが、これからも寄り添うように</h3><p>この記事の聖句はすべて聖書から引用しています。虹の聖書ウィジェットなら、いつでも聖書を読み、毎日の聖句ウィジェットを設定できます。会いたい日に、小さな灯りとなりますように。</p><div class="pl-bible-shots"><figure><img src="'+p+'" alt="虹の聖書ウィジェット — 2 テモテ 2:13" loading="lazy"><figcaption>ホーム画面に毎日の聖句</figcaption></figure><figure><img src="'+n+'" alt="虹の聖書 — 天国にいるペット トピック、マタイ 10:29-31" loading="lazy"><figcaption>「天国にいるペット」テーマで聖書を</figcaption></figure></div><a class="pl-bible-download" href="https://apps.apple.com/app/id6756217525">App Storeで虹の聖書ウィジェットを入手</a></div>',8)])])}const b=t(r,[["render",i]]);export{g as __pageData,b as default};
